∀ (s : Bool) (e : Fin 2047) (f : BitVec 52),
  NativeBridge.Incremental.PrimFloatSqrt.squareRoot (some (Sum.inl (s, e, f))) =
    if NativeBridge.Incremental.PrimFloatRepresentation.isZero (some (Sum.inl (s, e, f))) = true then
      some (Sum.inl (s, e, f))
    else
      if s = true then none
      else
        have k :=
          ↑(NativeBridge.Incremental.PrimFloatRepresentation.mantissa (some (Sum.inl (s, e, f)))).log2 +
            NativeBridge.Incremental.PrimFloatRepresentation.exponent (some (Sum.inl (s, e, f)));
        have q := max (-1074) (k / 2 - 52);
        have shift := NativeBridge.Incremental.PrimFloatRepresentation.exponent (some (Sum.inl (s, e, f))) - 2 * q;
        have n :=
          if shift < 0 then NativeBridge.Incremental.PrimFloatRepresentation.mantissa (some (Sum.inl (s, e, f)))
          else NativeBridge.Incremental.PrimFloatRepresentation.mantissa (some (Sum.inl (s, e, f))) * 2 ^ shift.toNat;
        have d := if shift < 0 then 2 ^ (-shift).toNat else 1;
        have m := (n / d).sqrt;
        have mid := d * (2 * m + 1) ^ 2;
        have m := if (decide (4 * n > mid) || 4 * n == mid && m % 2 == 1) = true then m + 1 else m;
        NativeBridge.Incremental.PrimFloatArithmetic.pack false m q

∀ (b c : Int) (qr : Int × Int),
  NativeBridge.Incremental.BinaryDivision.zDivStep b c qr =
    if 2 * qr.snd + c < b then (2 * qr.fst, 2 * qr.snd + c) else (2 * qr.fst + 1, 2 * qr.snd + c - b)

∀ (m : Nat) (e target : Int),
  NativeBridge.Incremental.SpecFloatShift.alignment m e target =
    if target < e then (2 ^ (e - target).toNat * m, target) else (m, e)

∀ (q r : Int),
  NativeBridge.Incremental.SpecFloatSqrt.sqrtLocation q r =
    if r = 0 then none else some (if r ≤ q then Ordering.lt else Ordering.gt)

∀ (steps k : Int),
  NativeBridge.Incremental.SpecFloatRounding.oddLocation steps k =
    if k = 0 then none else NativeBridge.Incremental.SpecFloatRounding.oddCompareResult (compare (2 * k + 1) steps)
